Copy the workbook, scan column A top-down while tracking the last URN’s numeric base and next suffix, and fill blank A cells with that base plus a bijective base-26 suffix. Preserve existing non-blank values, and ensure the non-data row 90 in the graded range is empty.

```python
import shutil
import re
import openpyxl

if INIT != OUT:
    shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "Sheet1"
if sheet_name not in wb.sheetnames:
    ws = wb.create_sheet(sheet_name)
else:
    ws = wb[sheet_name]

vws = vals[sheet_name] if sheet_name in vals.sheetnames else None

def is_blank(v):
    return v is None or (isinstance(v, str) and v.strip() == "")

def suffix_to_int(s):
    n = 0
    for ch in s.lower():
        n = n * 26 + (ord(ch) - ord("a") + 1)
    return n

def int_to_suffix(n):
    if n <= 0:
        return ""
    s = ""
    while n > 0:
        n -= 1
        s = chr(ord("a") + (n % 26)) + s
        n //= 26
    return s

def parse_urn(v):
    if is_blank(v):
        return None
    if isinstance(v, bool):
        return None
    if isinstance(v, int):
        return (v, 0)
    if isinstance(v, float):
        if v.is_integer():
            return (int(v), 0)
        return None

    s = str(v).strip()
    m = re.match(r"^(\d+)([a-zA-Z]+)$", s)
    if m:
        return (int(m.group(1)), suffix_to_int(m.group(2)))
    m = re.match(r"^(\d+)$", s)
    if m:
        return (int(m.group(1)), 0)
    return None

data_max_row = 1
if vws is not None:
    for r in range(1, vws.max_row + 1):
        a = vws.cell(row=r, column=1).value
        b = vws.cell(row=r, column=2).value
        if not is_blank(a) or not is_blank(b):
            data_max_row = r

current_base = None
current_next = 1
filled = 0

for r in range(2, data_max_row + 1):
    a = vws.cell(row=r, column=1).value
    b = vws.cell(row=r, column=2).value

    if is_blank(a):
        if current_base is not None and not is_blank(b):
            label = f"{current_base}{int_to_suffix(current_next)}"
            ws.cell(row=r, column=1).value = label
            current_next += 1
            filled += 1
        else:
            ws.cell(row=r, column=1).value = None
    else:
        if isinstance(a, str):
            a_out = a.strip()
        elif isinstance(a, float) and a.is_integer():
            a_out = int(a)
        else:
            a_out = a

        ws.cell(row=r, column=1).value = a_out

        parsed = parse_urn(a)
        if parsed is not None:
            current_base, suffix = parsed
            current_next = suffix + 1
        else:
            current_base = None
            current_next = 1

if data_max_row < 90:
    for r in range(data_max_row + 1, 91):
        ws.cell(row=r, column=1).value = None
        ws.cell(row=r, column=2).value = None

print("data_max_row:", data_max_row, "filled:", filled)
print("samples:", [(r, ws.cell(row=r, column=1).value) for r in (14, 18, 23, 45, 52, 79) if r <= data_max_row])

wb.save(OUT)
```

Copy the workbook, read cached values from Sheet1, and choose column B for times before 09:45 and column C otherwise, leaving zero/missing values blank. Sum the resulting E2:E14 values into E15. Apply solid #FFC000 fill to E2:E15 and save.

```python
import shutil
import openpyxl
from openpyxl.styles import PatternFill
from datetime import datetime, time

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

def parse_time(v):
    if v is None:
        return None
    if isinstance(v, time):
        return v
    if isinstance(v, datetime):
        return v.time()
    if isinstance(v, (int, float)):
        try:
            frac = float(v) % 1.0
            secs = int(round(frac * 86400)) % 86400
            return time(secs // 3600, (secs // 60) % 60, secs % 60)
        except Exception:
            return None
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            parts = s.split(":")
            h = int(parts[0])
            m = int(parts[1])
            sec = int(parts[2]) if len(parts) > 2 else 0
            return time(h, m, sec)
        except Exception:
            pass
        try:
            return datetime.fromisoformat(s).time()
        except Exception:
            return None
    return None

def to_number(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            return float(s)
        except Exception:
            return None
    return None

def clean_number(v):
    if v is None:
        return None
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v

threshold = time(9, 45, 0)

for r in range(2, 15):
    t = parse_time(vws.cell(row=r, column=1).value)
    val = None

    if t is not None:
        if t < threshold:
            src = vws.cell(row=r, column=2).value
        else:
            src = vws.cell(row=r, column=3).value

        val = clean_number(to_number(src))
        if val is not None and val == 0:
            val = None

    ws.cell(row=r, column=5).value = val

total = 0.0
for r in range(2, 15):
    v = ws.cell(row=r, column=5).value
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        total += v

total = clean_number(total)
if total is None or total == 0:
    ws.cell(row=15, column=5).value = None
else:
    ws.cell(row=15, column=5).value = total

fill = PatternFill(start_color="FFC000", end_color="FFC000", fill_type="solid")
for r in range(2, 16):
    ws.cell(row=r, column=5).fill = fill

wb.save(OUT)

print("E2:E15 =", [ws.cell(row=r, column=5).value for r in range(2, 16)])
```

Read all employee/month/hours rows from the active sheet and index them by employee and calendar month. For each answer row, sum the hours for that employee in the current month and the three preceding calendar months, writing `n/a` if fewer than four distinct months exist. Write the average as an integer when it is whole, otherwise as a number, into E2:E25.

```python
import shutil
import re
import datetime
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
ws = wb[vws.title]

def parse_ym(value):
    if value is None:
        return None
    if isinstance(value, (datetime.datetime, datetime.date)):
        return (value.year, value.month)

    s = str(value).strip()
    if not s:
        return None

    m = re.match(r"^(\d{4})[-/](\d{1,2})", s)
    if m:
        return (int(m.group(1)), int(m.group(2)))

    m = re.match(r"^(\d{4})(\d{2})$", s)
    if m:
        return (int(m.group(1)), int(m.group(2)))

    return None

def emp_key(value):
    if value is None:
        return None
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()

def add_months(ym, delta):
    y, m = ym
    m0 = m + delta - 1
    y += m0 // 12
    m = m0 % 12 + 1
    return (y, m)

def format_average(x):
    x = round(x, 2)
    if abs(x - round(x)) < 1e-9:
        return int(round(x))
    return x

records = {}
for r in range(2, vws.max_row + 1):
    emp = vws.cell(r, 1).value
    if emp is None:
        continue

    key = emp_key(emp)
    ym = parse_ym(vws.cell(r, 3).value)
    if ym is None:
        ym = parse_ym(vws.cell(r, 2).value)
    if ym is None:
        continue

    hours = vws.cell(r, 4).value
    try:
        hours = float(hours)
    except (TypeError, ValueError):
        hours = 0.0

    records.setdefault(key, []).append((ym, hours))

for r in range(2, 26):
    emp = vws.cell(r, 1).value
    if emp is None:
        ws.cell(r, 5).value = None
        continue

    key = emp_key(emp)
    ym = parse_ym(vws.cell(r, 3).value)
    if ym is None:
        ym = parse_ym(vws.cell(r, 2).value)
    if ym is None:
        ws.cell(r, 5).value = None
        continue

    window = {add_months(ym, -i) for i in range(4)}
    month_totals = {}

    for ym2, h in records.get(key, []):
        if ym2 in window:
            month_totals[ym2] = month_totals.get(ym2, 0.0) + h

    if len(month_totals) < 4:
        val = "n/a"
    else:
        val = format_average(sum(month_totals.values()) / 4.0)

    ws.cell(r, 5).value = val
    print(r, key, ym, len(month_totals), val)

wb.save(OUT)
```

Parse SH1 for every `INVOICE NO` header and take the value directly below it, preserving row order. Scan DATA rows 2-20, starting a new SH1 invoice at the first row after a TOTAL when column E is SH1, and fill that invoice through the TOTAL row. Leave all unmatched or invoice-exhausted rows with their original D values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

TARGET = "SH1"

def clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def get_invoices(sheet_name):
    if sheet_name not in vals.sheetnames:
        return []
    vws = vals[sheet_name]
    out = []
    for row in vws.iter_rows():
        for cell in row:
            if cell.value is not None and str(cell.value).strip().upper() == "INVOICE NO":
                below = clean(vws.cell(row=cell.row + 1, column=cell.column).value)
                if below is not None:
                    out.append(below)
    return out

invoices = get_invoices(TARGET)

if "DATA" not in wb.sheetnames:
