Copy the workbook, read the cached values from `RateHurdles` and `Deposits`, then scan `RateHurdles` in row order for the first row matching type, salesperson, and a date range containing the deposit date. Write the matched rate as a plain value into `Deposits!A2:A3`.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

rate_ws = vals["RateHurdles"]
dep_ws = vals["Deposits"]
out_ws = wb["Deposits"]

def to_datetime(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime(value.year, value.month, value.day)
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return datetime(1899, 12, 30) + timedelta(days=float(value))

    s = str(value).strip()
    formats = (
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%m/%d/%Y %H:%M:%S",
        "%m/%d/%Y",
    )
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None

for r in range(2, dep_ws.max_row + 1):
    dep_type = dep_ws.cell(row=r, column=2).value
    dep_person = dep_ws.cell(row=r, column=3).value
    dep_date = to_datetime(dep_ws.cell(row=r, column=4).value)

    if dep_type is None or dep_person is None or dep_date is None:
        out_ws.cell(row=r, column=1).value = None
        continue

    dep_type_s = str(dep_type).strip()
    dep_person_s = str(dep_person).strip()
    found_rate = None

    for rr in range(2, rate_ws.max_row + 1):
        start = to_datetime(rate_ws.cell(row=rr, column=1).value)
        end = to_datetime(rate_ws.cell(row=rr, column=2).value)
        rate_type = rate_ws.cell(row=rr, column=3).value
        rate_person = rate_ws.cell(row=rr, column=4).value
        rate = rate_ws.cell(row=rr, column=5).value

        if rate_type is None or rate_person is None or start is None or end is None:
            continue

        if (
            str(rate_type).strip() == dep_type_s
            and str(rate_person).strip() == dep_person_s
            and start <= dep_date <= end
        ):
            found_rate = rate
            break

    if found_rate is None:
        out_ws.cell(row=r, column=1).value = None
    else:
        try:
            out_ws.cell(row=r, column=1).value = float(found_rate)
        except (TypeError, ValueError):
            out_ws.cell(row=r, column=1).value = found_rate

    print(f"Deposits row {r}: {dep_type_s} | {dep_person_s} | {dep_date} -> {found_rate}")

wb.save(OUT)
```

Use the active sheet and read A/B/D from the cached workbook. For each E2:E7 row, return the B value from the same row when D matches A; otherwise fall back to the nth occurrence of D in A, blanking numeric zeros. Then write plain values and apply the requested fill, Calibri font, and zero-as-blank number format to E2:E9.

```python
import shutil
import openpyxl
from openpyxl.styles import PatternFill, Font

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title] if ws.title in vals.sheetnames else vals.active

max_row = max(vws.max_row, ws.max_row, 9)

def key(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return float(v)
    return str(v).strip()

def is_zero(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, (int, float)):
        return v == 0
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return False
        try:
            return float(s) == 0.0
        except ValueError:
            return False
    return False

A = [key(vws.cell(r, 1).value) for r in range(1, max_row + 1)]
B = [vws.cell(r, 2).value for r in range(1, max_row + 1)]
D = [key(vws.cell(r, 4).value) for r in range(1, max_row + 1)]

for r in range(2, 8):
    d = D[r - 1]
    result = None

    if d is not None:
        # Preferred: same-row match, as requested.
        if A[r - 1] == d:
            result = B[r - 1]
        else:
            # Fallback: nth occurrence of the lookup value in column A.
            cnt = sum(1 for i in range(2, r + 1) if D[i - 1] == d)
            seen = 0
            for s in range(2, max_row + 1):
                if A[s - 1] == d:
                    seen += 1
                    if seen == cnt:
                        result = B[s - 1]
                        break

            # Last resort: first match.
            if result is None:
                for s in range(2, max_row + 1):
                    if A[s - 1] == d:
                        result = B[s - 1]
                        break

    if is_zero(result):
        result = None

    if isinstance(result, str):
        result = result.strip()

    ws.cell(row=r, column=5).value = result
    print(r, repr(result))

fill = PatternFill(start_color="FCE4D6", end_color="FCE4D6", fill_type="solid")
font = Font(name="Calibri")
numfmt = "General;General;;@"

for r in range(2, 10):
    c = ws.cell(row=r, column=5)
    c.fill = fill
    c.font = font
    c.number_format = numfmt

wb.save(OUT)
```

Plan: copy the workbook, build a lookup from the data rows using client + representative name to percentage, then fill D21:D23 on the active sheet with the matching percentages.

