Plan: Copy the workbook, read the non-empty values from column H on the active sheet, and compute their unique sorted list. Write the first six values into Q2:V2, leaving any remaining answer cells empty. Save the result workbook.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active if vals.active is not None else vals.worksheets[0]
ws = wb.active if wb.active is not None else wb.worksheets[0]

def normalize(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        if isinstance(value, float) and value.is_integer():
            return int(value)
        return value
    s = str(value).strip()
    if s == "":
        return None
    try:
        f = float(s)
        if f.is_integer():
            return int(f)
        return f
    except Exception:
        return s

raw_values = []
for row in range(2, vws.max_row + 1):
    v = vws.cell(row=row, column=8).value  # column H
    if v is None:
        continue
    n = normalize(v)
    if n is None:
        continue
    raw_values.append(n)

unique_sorted = sorted(
    set(raw_values),
    key=lambda x: (0, x) if isinstance(x, (int, float)) and not isinstance(x, bool) else (1, str(x))
)

# Answer region: Q2:V2 = 6 cells
for i in range(6):
    cell = ws.cell(row=2, column=17 + i)  # Q=17, R=18, ..., V=22
    cell.value = unique_sorted[i] if i < len(unique_sorted) else None

wb.save(OUT)

