```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "Sheet1"
vws = vals[sheet_name]
ws = wb[sheet_name]

unit_cols = [2, 3, 4, 5, 6]  # B:F
res_col = 9                  # I

def to_num(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return None
    if isinstance(x, (int, float)):
        return float(x)
    try:
        return float(str(x).strip())
    except Exception:
        return None

# Locate min/max rows dynamically, with fallback to the known layout.
min_row = max_row = None
for r in range(1, vws.max_row + 1):
    a = vws.cell(r, 1).value
    if isinstance(a, str):
        s = a.strip().lower()
        if s == "min":
            min_row = r
        elif s == "max":
            max_row = r

if min_row is None:
    min_row = 20
if max_row is None:
    max_row = 21

mins = [to_num(vws.cell(min_row, c).value) or 0.0 for c in unit_cols]
maxs = [to_num(vws.cell(max_row, c).value) or 0.0 for c in unit_cols]

processed = 0

for r in range(2, vws.max_row + 1):
    # Do not treat the min/max label rows as data rows.
    a = vws.cell(r, 1).value
    if isinstance(a, str) and a.strip().lower() in {"min", "max"}:
        continue

    res = to_num(vws.cell(r, res_col).value)
    if res is None:
        continue

    orig_units = [vws.cell(r, c).value for c in unit_cols]
    units = [0.0 if to_num(u) is None else to_num(u) for u in orig_units]
    changed = [False] * 5

    rem = res

    if rem > 0:
        # Positive residual: add from unit1 to unit5.
        for i in range(5):
            if rem <= 1e-9:
                break
            if units[i] == 0:
                continue
            cap = maxs[i] - units[i]
            if cap <= 0:
                continue
            adj = min(rem, cap)
            if adj > 0:
                units[i] += adj
                rem -= adj
                changed[i] = True

    elif rem < 0:
        # Negative residual: subtract from unit5 to unit1.
        need = -rem
        for i in range(4, -1, -1):
            if need <= 1e-9:
                break
            if units[i] == 0:
                continue
            cap = units[i] - mins[i]
            if cap <= 0:
                continue
            adj = min(need, cap)
            if adj > 0:
                units[i] -= adj
                need -= adj
                changed[i] = True

    # Write adjusted unit values back in place.
    for i, c in enumerate(unit_cols):
        if orig_units[i] is not None or changed[i]:
            val = units[i]
            if abs(val - round(val)) < 1e-9:
                val = int(round(val))
            ws.cell(r, c).value = val

    # Final instruction: set residual column values to 0.
    ws.cell(r, res_col).value = 0
    processed += 1

wb.save(OUT)

print("processed rows:", processed)
for r in (2, 3, 8, 16):
    print(r, [ws.cell(r, c).value for c in unit_cols], ws.cell(r, res_col).value)
