Scan rows from 5 downward in Sheet1 and treat each contiguous non-empty block in A:X as one group. For each group, compare column K values, marking Y for the maximum (all ties) and N otherwise, with single-row groups as Y. Write the resulting Y/N values into Z5:Z43, leaving non-data rows empty.

```python
import shutil
import openpyxl
import math

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

SHEET = "Sheet1"
if SHEET not in wb.sheetnames:
    wb.create_sheet(SHEET)
ws = wb[SHEET]

if SHEET not in vals.sheetnames:
    vws = vals.create_sheet(SHEET)
else:
    vws = vals[SHEET]

START_ROW = 5
ANSWER_END_ROW = 43
LAST_DATA_COL = 24  # X
K_COL = 11          # K
Z_COL = 26          # Z

def has_data(row):
    for col in range(1, LAST_DATA_COL + 1):
        v = vws.cell(row=row, column=col).value
        if v is None:
            continue
        if isinstance(v, str) and not v.strip():
            continue
        return True
    return False

def get_k(row):
    v = vws.cell(row=row, column=K_COL).value
    if v is None:
        return None
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    try:
        return float(str(v).strip().replace(",", ""))
    except Exception:
        return None

last_row = max(vws.max_row or 0, ANSWER_END_ROW)

groups = []
r = START_ROW
while r <= last_row:
    if has_data(r):
        r2 = r
        while r2 + 1 <= last_row and has_data(r2 + 1):
            r2 += 1
        groups.append((r, r2))
        r = r2 + 1
    else:
        r += 1

# Ensure the answer region starts clean.
for r in range(START_ROW, ANSWER_END_ROW + 1):
    ws.cell(row=r, column=Z_COL).value = None

for r1, r2 in groups:
    size = r2 - r1 + 1
    k_values = [get_k(r) for r in range(r1, r2 + 1)]
    valid_values = [x for x in k_values if x is not None]
    max_value = max(valid_values) if valid_values else None

    for i, r in enumerate(range(r1, r2 + 1)):
        if size == 1:
            result = "Y"
        elif max_value is None:
            result = "N"
        else:
            kv = k_values[i]
            result = "Y" if kv is not None and math.isclose(kv, max_value, rel_tol=0.0, abs_tol=1e-9) else "N"

        if START_ROW <= r <= ANSWER_END_ROW:
            ws.cell(row=r, column=Z_COL).value = result

wb.save(OUT)

print("groups:", groups)
print("answers:", [(r, ws.cell(row=r, column=Z_COL).value) for r in range(START_ROW, ANSWER_END_ROW + 1) if ws.cell(row=r, column=Z_COL).value is not None])
```

I will read the cached values from Munka1 and treat each comment as a string of tokens separated by non-letter/digit characters. For each of G2:G5, I will find the first ID whose comment contains both parameters as whole tokens, using case-insensitive matching. I will write those IDs as plain values, leaving unmatched cells empty.

```python
import shutil
import re
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

data_ws = vals["Munka1"]
ans_ws = wb["Munka1"]

def clean(v):
    if v is None:
        return ""
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    return str(v).strip()

pattern_cache = {}

def has_param(comment, param):
    if not param:
        return True
    pat = pattern_cache.get(param)
    if pat is None:
        # Boundary: previous/next character must not be a Unicode letter/digit.
        # Underscore is treated as a boundary, while dashes/slashes/spaces are separators.
        pat = re.compile(
            r"(?<![^\W_])" + re.escape(param) + r"(?![^\W_])",
            re.IGNORECASE
        )
        pattern_cache[param] = pat
    return pat.search(comment) is not None

max_row = data_ws.max_row
print("max_row:", max_row)

for q in range(2, 6):
    p1 = clean(data_ws.cell(row=q, column=5).value)
    p2 = clean(data_ws.cell(row=q, column=6).value)
    params = [p for p in (p1, p2) if p]

    found = None
    if params:
        for r in range(2, max_row + 1):
            comment = clean(data_ws.cell(row=r, column=2).value)
            if not comment:
                continue

            if all(has_param(comment, p) for p in params):
                found = data_ws.cell(row=r, column=1).value
                if found is not None:
                    if isinstance(found, str):
                        found = found.strip()
                    break

    ans_ws.cell(row=q, column=7).value = found
    print(q, params, "->", found)

wb.save(OUT)
```

I will read cached values from the active sheet and, for each row 4–75, use R/S/T as the three criteria (falling back to N/O/P only if R/S/T are blank). I will sum the C4:M75 cells whose row matches A/B and whose column header in C3:M3 matches the third criterion. I will write the resulting plain numbers into U4:U75 and save the workbook.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
try:
    vws = vals[ws.title]
except KeyError:
    vws = vals.active

def norm(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def eq(a, b):
    a = norm(a)
    b = norm(b)

    if a is None and b is None:
        return True
    if a is None or b is None:
        return False

    if isinstance(a, str) and isinstance(b, str):
        return a.casefold() == b.casefold()

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    try:
        return float(a) == float(b)
    except Exception:
        return False

def to_num(v):
    if v is None:
        return 0
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return 0
        try:
            return float(s)
        except Exception:
            return 0
    return 0

def get_crit(row, primary_col, fallback_col):
    v = vws.cell(row=row, column=primary_col).value
    if v is None or (isinstance(v, str) and not v.strip()):
        v = vws.cell(row=row, column=fallback_col).value
    return norm(v)

results = []

for r in range(4, 76):
    crit_a = get_crit(r, 18, 14)  # R, fallback N
    crit_b = get_crit(r, 19, 15)  # S, fallback O
    crit_h = get_crit(r, 20, 16)  # T, fallback P

    total = 0

    for i in range(4, 76):
        a = vws.cell(row=i, column=1).value
        b = vws.cell(row=i, column=2).value

        if not eq(a, crit_a) or not eq(b, crit_b):
            continue

        for j in range(3, 14):  # C through M
            header = vws.cell(row=3, column=j).value
            if eq(header, crit_h):
                total += to_num(vws.cell(row=i, column=j).value)

    if isinstance(total, float) and total.is_integer():
        total = int(total)

    ws.cell(row=r, column=21).value = total
    results.append(total)

print("rows:", len(results), "first:", results[:5], "last:", results[-5:])
wb.save(OUT)
