def to_time(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, dt.time):
        return value
    if isinstance(value, dt.datetime):
        return value.time()
    if isinstance(value, dt.date):
        return dt.time(0, 0, 0)
    if isinstance(value, (int, float)):
        frac = float(value) % 1.0
        total_seconds = int(round(frac * 86400)) % 86400
        h, rem = divmod(total_seconds, 3600)
        m, s = divmod(rem, 60)
        return dt.time(h, m, s)
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        formats = (
            "%H:%M:%S",
            "%H:%M",
            "%I:%M:%S %p",
            "%I:%M %p",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d %H:%M",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y %H:%M",
        )
        for fmt in formats:
            try:
                return dt.datetime.strptime(s, fmt).time()
            except ValueError:
                pass
        try:
            return dt.datetime.fromisoformat(s).time()
        except Exception:
            return None
    return None


def in_time_range(t, start, end):
    if t is None:
        return False
    if start is None and end is None:
        return True
    if start is None:
        return t <= end
    if end is None:
        return t >= start
    if start <= end:
        return start <= t <= end
    return t >= start or t <= end


