shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title] if ws.title in vals.sheetnames else vals.active

MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12
}

def parse_side(raw):
    if raw is None:
        return None

    s = str(raw).strip()
    if not s:
        return None

    # Remove ordinal suffixes like 2nd, 5th, etc.
    s = re.sub(r"(\d{1,2})(st|nd|rd|th)\b", r"\1", s, flags=re.IGNORECASE)

    # Try common explicit date formats.
    formats = [
        "%m/%d", "%m-%d", "%m.%d",
        "%d/%m", "%d-%m", "%d.%m",
        "%m/%d/%Y", "%m-%d-%Y",
        "%Y/%m/%d", "%Y-%m-%d"
    ]
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            pass

    # Month name + day, e.g. "June 2"
    m = re.match(r"^([A-Za-z]+)\s+(\d{1,2})$", s)
    if m:
        key = m.group(1).lower()[:3]
        if key in MONTHS:
            try:
                return date(2000, MONTHS[key], int(m.group(2)))
            except ValueError:
                pass

    # Day + month name, e.g. "2 June"
    m = re.match(r"^(\d{1,2})\s+([A-Za-z]+)$", s)
    if m:
        key = m.group(2).lower()[:3]
        if key in MONTHS:
            try:
                return date(2000, MONTHS[key], int(m.group(1)))
            except ValueError:
                pass

    # Bare day number: interpret as a day in June, matching the example.
    m = re.search(r"\d{1,2}", s)
    if m:
        day = int(m.group())
        if 1 <= day <= 31:
            return date(2000, 6, day)

    return None

def inclusive_days(text):
    if text is None:
        return None

    s = str(text).strip()
    if not s:
        return None

    # Split on "to"
    parts = re.split(r"\s+to\s+|\bto\b", s, maxsplit=1, flags=re.IGNORECASE)
    if len(parts) == 2:
        d1 = parse_side(parts[0])
        d2 = parse_side(parts[1])
        if d1 is not None and d2 is not None:
            return abs((d2 - d1).days) + 1

    # Fallback: use the first two numbers found.
    nums = re.findall(r"\d+", s)
    if len(nums) >= 2:
        return abs(int(nums[1]) - int(nums[0])) + 1

    return None

a_val = vws["A2"].value
if a_val is None and "Sheet1" in vals.sheetnames:
    a_val = vals["Sheet1"]["A2"].value

result = inclusive_days(a_val)
ws["B2"] = int(result) if result is not None else None

print("active sheet:", ws.title)
print("A2:", repr(a_val))
print("B2:", ws["B2"].value)

wb.save(OUT)
```

Read the active sheet and extract the inclusive date criteria from P6/Q6 and time criteria from R3/R4. Loop over the grid, summing numeric cells whose column-A date and row-1 time satisfy both ranges. Write the rounded total as a plain value into R6.

```python
import shutil
import openpyxl
from datetime import datetime, date, time, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
if vws is None:
    vws = vals["Sheet1"]
ws = wb[vws.title]

def to_date(v):
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, date):
        return v
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return date(1899, 12, 30) + timedelta(days=int(v))
    if isinstance(v, str):
        s = v.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y %H:%M:%S", "%m/%d/%Y"):
            try:
                return datetime.strptime(s, fmt).date()
            except ValueError:
                pass
    return None

def to_time(v):
    if isinstance(v, time):
        return v
    if isinstance(v, datetime):
        return v.time()
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        frac = float(v) % 1.0
        secs = int(round(frac * 86400))
        return time((secs // 3600) % 24, (secs // 60) % 60, secs % 60)
    if isinstance(v, str):
        s = v.strip()
        for fmt in ("%H:%M:%S", "%H:%M"):
            try:
                return datetime.strptime(s, fmt).time()
            except ValueError:
                pass
    return None

d_from = to_date(vws["P6"].value)
d_to = to_date(vws["Q6"].value)
t_from = to_time(vws["R3"].value)
t_to = to_time(vws["R4"].value)

total = 0.0
count = 0

for r in range(2, vws.max_row + 1):
    d = to_date(vws.cell(row=r, column=1).value)
    if d is None:
        continue

    if d_from is not None and d_to is not None:
        if d_from <= d_to:
            if not (d_from <= d <= d_to):
                continue
        else:
            if not (d >= d_from or d <= d_to):
                continue

    for c in range(2, vws.max_column + 1):
        t = to_time(vws.cell(row=1, column=c).value)
        if t is None:
            continue

        if t_from is not None and t_to is not None:
            if t_from <= t_to:
                if not (t_from <= t <= t_to):
                    continue
            else:
                if not (t >= t_from or t <= t_to):
                    continue

        val = vws.cell(row=r, column=c).value
        if isinstance(val, (int, float)) and not isinstance(val, bool):
            total += float(val)
            count += 1

ws["R6"] = round(total, 2)
wb.save(OUT)

print("sheet:", ws.title)
print("criteria:", d_from, d_to, t_from, t_to)
print("count:", count, "total:", total)
