def normalize_number(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return x
    if isinstance(x, float) and x.is_integer():
        return int(x)
    if isinstance(x, str):
        s = x.strip()
        if not s:
            return None
        try:
            f = float(s)
            return int(f) if f.is_integer() else f
        except ValueError:
