        if a_s == "work" and b_s == "material":
            data_header = row[0].row
        elif a_s == "work" and b_s == "category type":
            report_header = row[0].row

    return data_header, report_header


def norm_work(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, (int, float)):
        f = float(v)
        return str(int(f)) if f.is_integer() else str(f)

    s = str(v).strip()
    if not s:
        return None

    try:
        f = float(s)
        return str(int(f)) if f.is_integer() else str(f)
    except ValueError:
        return s


def norm_text(v):
    if v is None:
        return None
    s = str(v).strip()
    return s.casefold() if s else None


rws = vals[answer_title] if answer_title in vals.sheetnames else vals.active

