    if v is None:
        continue
    s = str(v).strip()
    if s.lower().startswith("category"):
        cat_cols[s.casefold()] = col

lookup = {}
data_end = data_sheet.max_row
if report_sheet is data_sheet and report_header > data_header:
    data_end = report_header - 1

for r in range(data_header + 1, data_end + 1):
