# Clear the graded answer region.
for r in range(3, 971):
    for c in range(1, 4):
        tws.cell(row=r, column=c).value = None

out_r = 3
for r, item in item_rows:
    for c, dt in date_cols:
        if out_r > 970:
            break
        qty = to_number(dws.cell(row=r, column=c).value)

        tws.cell(row=out_r, column=1).value = item

        date_cell = tws.cell(row=out_r, column=2)
        date_cell.value = dt
        date_cell.number_format = "yyyy-mm-dd hh:mm:ss"

        tws.cell(row=out_r, column=3).value = qty
        out_r += 1
    if out_r > 970:
        break

written = out_r - 3
print("date_cols:", len(date_cols), "item_rows:", len(item_rows), "written:", written)
if written:
    print("first:", tws.cell(row=3, column=1).value, tws.cell(row=3, column=2).value, tws.cell(row=3, column=3).value)
    print("last:", tws.cell(row=out_r - 1, column=1).value, tws.cell(row=out_r - 1, column=2).value, tws.cell(row=out_r - 1, column=3).value)

wb.save(OUT)
```

Plan: compute the ten year counts by scanning G14:G185 and J14:J185, matching “open” case-insensitively. Write the resulting integers into I2:I11 of the active sheet, unmerging only if an answer cell is merged. Save the workbook to OUT.

```python
import shutil
import openpyxl
from openpyxl.cell.cell import MergedCell
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
if ws is None:
    ws = wb[wb.sheetnames[0]]

vws = vals[ws.title] if ws.title in vals.sheetnames else vals.active

def has_values(sheet, rows, col=7):
    try:
        return any(sheet.cell(row=r, column=col).value is not None for r in rows)
    except Exception:
        return False

data_ws = vws
year_ws = vws

if "Cumulative" in vals.sheetnames:
    cws = vals["Cumulative"]
    if not has_values(vws, range(14, 186)) and has_values(cws, range(14, 186)):
        data_ws = cws
    if not has_values(vws, range(2, 12)) and has_values(cws, range(2, 12)):
        year_ws = cws

def norm_year(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, datetime):
        return v.year
    if isinstance(v, date):
        return v.year
    if isinstance(v, int):
        return v
    if isinstance(v, float):
        if v.is_integer():
            return int(v)
        return str(v).strip()

    s = str(v).strip()
    try:
        f = float(s)
        if f.is_integer():
            return int(f)
    except (ValueError, TypeError, OverflowError):
        pass
    return s

def is_open(v):
    if v is None:
        return False
    return str(v).strip().lower() == "open"

counts = {}
for r in range(2, 12):
    y = norm_year(year_ws.cell(row=r, column=7).value)
    counts[y] = 0

open_total = 0
for r in range(14, 186):
    y = norm_year(data_ws.cell(row=r, column=7).value)
    if is_open(data_ws.cell(row=r, column=10).value):
        open_total += 1
        if y is not None and y in counts:
            counts[y] += 1

def writable_cell(sheet, row, col):
    cell = sheet.cell(row=row, column=col)
    if isinstance(cell, MergedCell):
        for rng in list(sheet.merged_cells.ranges):
            if rng.min_row <= row <= rng.max_row and rng.min_col <= col <= rng.max_col:
                sheet.unmerge_cells(str(rng))
                break
        cell = sheet.cell(row=row, column=col)
    return cell

for r in range(2, 12):
    y = norm_year(year_ws.cell(row=r, column=7).value)
    cell = writable_cell(ws, r, 9)
    cell.value = int(counts.get(y, 0))

wb.save(OUT)

print("sheets:", wb.sheetnames, "active:", ws.title)
print("year_counts:", {str(k): v for k, v in counts.items()})
print("open_total:", open_total)
