Use the active sheet as the answer sheet. Combine the two vertical criteria into one row match and the two horizontal criteria into one column match, then read the corresponding value from the data table. Write that plain value to AE5.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
ws = wb.active

def clean(x):
    if x is None:
        return None
    if isinstance(x, str):
        s = x.strip()
        return s if s != "" else None
    return x

def as_number(x):
    if isinstance(x, bool):
        return None
    if isinstance(x, (int, float)):
        return float(x)
    if isinstance(x, str):
        s = x.strip()
        if s == "":
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None

def same(a, b):
    a = clean(a)
    b = clean(b)
    if a is None or b is None:
        return a is None and b is None
    na = as_number(a)
    nb = as_number(b)
    if na is not None and nb is not None:
        return na == nb
