def norm_key(x):
    if x is None:
        return None
    if isinstance(x, str):
        return x.lower()
    return x

def to_num(x):
    if x is None:
        return 0.0
    if isinstance(x, (int, float)):
        return float(x)
    if isinstance(x, str):
        s = x.strip()
        if s == "":
            return 0.0
        try:
            return float(s)
        except ValueError:
