def norm_key(x):
    if isinstance(x, bool):
        return x
    if isinstance(x, (int, float)):
        if isinstance(x, float) and x.is_integer():
            return int(x)
        return x
    if isinstance(x, str):
        s = x.strip()
        if not s:
            return None
        try:
            f = float(s)
            if f.is_integer():
                return int(f)
            return f
        except (ValueError, OverflowError):
            return s
    return x

def clean_value(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return x
    if isinstance(x, float) and x.is_integer():
        return int(x)
    if isinstance(x, str):
        s = x.strip()
        return s if s else None
    return x

# Master cycle table is in rows 2-8, columns C-H, keyed by column B.
