import shutil
import openpyxl
import re
import math
from openpyxl.utils import range_boundaries

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb.active
vws = vals[ws.title]


def is_num(x):
    return (
        isinstance(x, (int, float))
        and not isinstance(x, bool)
        and not (isinstance(x, float) and math.isnan(x))
    )


def num_val(sheet, coord, default=0.0):
    v = sheet[coord].value
    return v if is_num(v) else default


def sum_range(sheet, rng):
    min_col, min_row, max_col, max_row = range_boundaries(rng)
    total = 0.0
    for r in range(min_row, max_row + 1):
        for c in range(min_col, max_col + 1):
            v = sheet.cell(row=r, column=c).value
            if is_num(v):
                total += v
    return total


def computed_ref(ref):
    if ref == "E31":
        den = (
            num_val(vws, "C19")
            + num_val(vws, "C20")
            + sum_range(vws, "C7:C11")
            + num_val(vws, "C21")
        )
        if den:
            return num_val(vws, "C5") / den
        return None

    if ref == "E32":
        den = (
            num_val(vws, "C23")
            + num_val(vws, "C24")
            + sum_range(vws, "D7:D16")
        )
        if den:
            return num_val(vws, "D5") / den
        return None

    if ref == "E30":
        c17 = num_val(vws, "C34") + num_val(vws, "C5")
        den = (
            sum_range(vws, "C7:C11")
            + sum_range(vws, "D7:D16")
            + sum_range(vws, "C19:C24")
        )
        if den:
            return c17 / den
        return None

    return None


def ref_value(ref):
    if not ref:
        return None
    v = vws[ref].value
    if is_num(v):
        return v
    return computed_ref(ref)


def formula_c_ref(row):
    v = ws.cell(row=row, column=5).value
    if isinstance(v, str) and v.startswith("="):
        m = re.search(r",\s*([A-Z]{1,3}\d+)\s*,", v)
        if m:
            return m.group(1)
    return None


def default_c_ref(row):
    if 7 <= row <= 11:
        return "E31"
    if 12 <= row <= 15:
        return "E32"
    if row == 16:
        return "E35"
    return "E31"


def d_ref_for(c_ref, row):
    if c_ref == "E31":
        return "E32"
    if c_ref == "E32":
        return "E31"
    if 7 <= row <= 11:
        return "E32"
    if 12 <= row <= 15:
        return "E31"
    return "E32"


results = []
for row in range(7, 17):
    c = vws.cell(row=row, column=3).value
    d = vws.cell(row=row, column=4).value

    c_on = is_num(c) and c > 1
    d_on = is_num(d) and d > 1

    if c_on and not d_on:
        ref = formula_c_ref(row) or default_c_ref(row)
        val = ref_value(ref)
    elif d_on and not c_on:
        ref = d_ref_for(formula_c_ref(row), row)
        val = ref_value(ref)
    else:
        val = None

    if val is not None and isinstance(val, float) and val == 0:
        val = 0.0

    ws.cell(row=row, column=5).value = val
    results.append((row, c, d, val))

print("Answer sheet:", ws.title)
for row, c, d, val in results:
    print(row, repr(c), repr(d), repr(val))

wb.save(OUT)
