def is_blank_row(row_values):
    for v in row_values:
        if v is None:
            continue
        if isinstance(v, str) and v.strip() == "":
            continue
        return False
    return True


def num_or_none(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        f = float(v)
        if math.isnan(f) or math.isinf(f):
            return None
        return f
    if isinstance(v, str):
        s = v.strip()
        if s == "" or s.startswith("="):
            return None
        try:
            f = float(s)
            if math.isnan(f) or math.isinf(f):
                return None
            return f
        except Exception:
            return None
    return None


def round1(v):
    if v is None:
        return None
    f = float(v)
    r = round(f, 1)
    if r == int(r):
        return int(r)
    return r


def preserve_value(v, text=False):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
