I will read the active sheet’s inventory layers (beginning inventory plus PO-1 through PO-4) and current inventory from the cached values. For each row, I will allocate the current inventory from the newest layer backward under FIFO and divide the accumulated cost by current inventory. The script writes the resulting per-unit costs as plain numbers into M2:M5.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals.active

def to_float(value):
    if value is None:
        return 0.0
    if isinstance(value, bool):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    s = str(value).strip().replace(",", "")
    if not s:
        return 0.0
    try:
        return float(s)
    except ValueError:
        return 0.0

# Layers in chronological order:
# Beginning inventory, PO-1, PO-2, PO-3, PO-4
layer_cols = [
    (2, 3),   # B, C
    (4, 5),   # D, E
    (6, 7),   # F, G
    (8, 9),   # H, I
    (10, 11)  # J, K
]

for r in range(2, 6):
    current_raw = vws.cell(row=r, column=12).value  # Column L
    if current_raw is None:
        ws.cell(row=r, column=13).value = None
        print(f"row {r}: no current inventory")
        continue

    current = to_float(current_raw)
    layers = []

    for units_col, cost_col in layer_cols:
        units = to_float(vws.cell(row=r, column=units_col).value)
        cost = to_float(vws.cell(row=r, column=cost_col).value)
        if units > 0:
            layers.append((units, cost))

    remaining = current
    total_cost = 0.0

    # FIFO ending inventory: take from the most recent layers backward.
    for units, cost in reversed(layers):
        if remaining <= 0:
            break
        take = min(remaining, units)
        total_cost += take * cost
        remaining -= take

    if current > 0:
        per_unit_cost = total_cost / current
        if abs(per_unit_cost) < 1e-12:
            per_unit_cost = 0.0
        ws.cell(row=r, column=13).value = per_unit_cost
        print(f"row {r}: current={current}, per_unit_cost={per_unit_cost}")
    else:
        ws.cell(row=r, column=13).value = 0.0
        print(f"row {r}: current=0, per_unit_cost=0")

wb.save(OUT)
```

Load the cached values from Sheet1 and Sheet2, starting after the header row, and normalize each 7-column row for comparison. Compute unique rows present only in Sheet1 and only in Sheet2, preserving original order. Write those full rows as plain values to Sheet3 and Sheet4 from row 1, clearing any extra answer cells.

```python
import shutil
import openpyxl
from datetime import datetime, date, time

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)


def norm(v):
    if v is None:
        return ("e",)
    if isinstance(v, bool):
        return ("b", v)
    if isinstance(v, datetime):
        if v.time() == time(0, 0):
            return ("d", v.date().isoformat())
        return ("dt", v.isoformat())
    if isinstance(v, date):
        return ("d", v.isoformat())
    if isinstance(v, (int, float)):
        try:
            return ("n", round(float(v), 2))
        except Exception:
            return ("s", str(v).strip())

    s = str(v).strip()
    if s == "":
        return ("e",)
    try:
        return ("n", round(float(s), 2))
    except Exception:
        return ("s", s)


def find_start(ws):
    for r in range(1, ws.max_row + 1):
        a = ws.cell(row=r, column=1).value
        b = ws.cell(row=r, column=2).value
        if (
            isinstance(a, str)
            and isinstance(b, str)
            and a.strip().lower() == "date"
            and b.strip().lower() == "particulars"
        ):
            return r + 1
    return 9


def get_rows(sheet_name):
    ws = vals[sheet_name]
    start = find_start(ws)
    rows = []
    for r in range(start, ws.max_row + 1):
        raw = [ws.cell(row=r, column=c).value for c in range(1, 8)]
        if all(v is None or (isinstance(v, str) and v.strip() == "") for v in raw):
            continue
        key = tuple(norm(v) for v in raw)
        rows.append((key, raw))
    return rows


def clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s != "" else None
    return v


def write_sheet(sheet_name, rows):
    if sheet_name not in wb.sheetnames:
        ws = wb.create_sheet(sheet_name)
    else:
        ws = wb[sheet_name]

    max_clear = max(len(rows), 2, min(ws.max_row, 1000))
    for r in range(1, max_clear + 1):
        for c in range(1, 8):
            ws.cell(row=r, column=c).value = None

    for i, raw in enumerate(rows, start=1):
        for c in range(1, 8):
            ws.cell(row=i, column=c).value = clean(raw[c - 1])


rows1 = get_rows("Sheet1")
rows2 = get_rows("Sheet2")

keys1 = set(k for k, _ in rows1)
keys2 = set(k for k, _ in rows2)

out3 = []
seen = set()
for key, raw in rows1:
    if key not in keys2 and key not in seen:
        out3.append(raw)
        seen.add(key)

out4 = []
seen = set()
for key, raw in rows2:
    if key not in keys1 and key not in seen:
        out4.append(raw)
        seen.add(key)

write_sheet("Sheet3", out3)
write_sheet("Sheet4", out4)

wb.save(OUT)

print("Sheet3 rows:", len(out3))
for row in out3[:3]:
    print(row)
print("Sheet4 rows:", len(out4))
for row in out4[:3]:
    print(row)
```

