    if any(vws.cell(row=r, column=c).value is not None for r in (4, 5, 6)):
        last_col = c
if last_col < 3:
    last_col = 22

months = [to_num(vws.cell(row=4, column=c).value) for c in range(3, last_col + 1)]
sold = [to_num(vws.cell(row=5, column=c).value) for c in range(3, last_col + 1)]
accum_raw = [to_num(vws.cell(row=6, column=c).value) for c in range(3, last_col + 1)]

# Prefer recomputing the cumulative row from apples sold; fall back to cached accum row.
if any(s is not None for s in sold):
    accum = []
    total = 0
    for s in sold:
        total += s if s is not None else 0
        accum.append(total)
else:
    accum = accum_raw

# If month headers are missing, infer sequential month numbers.
if any(m is None for m in months):
    known = [(i, m) for i, m in enumerate(months) if m is not None]
    if not known:
        months = [float(i + 1) for i in range(len(months))]
    else:
        first_i, first_m = known[0]
        for i in range(first_i):
            months[i] = float(i + 1)
        last = first_m
        for i in range(first_i, len(months)):
            if months[i] is None:
                last += 1
                months[i] = last
            else:
                last = months[i]

def month_for_index(idx):
    if idx is None:
        return None

    # First cumulative month whose accumulated apples is >= the apple index.
    for i, a in enumerate(accum):
        if a is not None and a >= idx:
            if i < len(months) and months[i] is not None:
                return months[i]
            return float(i + 1)

    # Fallback for an index beyond the total: use the last month.
    if accum and months:
        return months[-1] if months[-1] is not None else float(len(accum))
    return None

filled = 0
for r in range(9, 101):
    idx = to_num(vws.cell(row=r, column=1).value)
    if idx is None:
        # Sample structure has A9:A100 = 1:92; use this only as a fallback.
        idx = float(r - 8)

    m = month_for_index(idx)
    ws.cell(row=r, column=2).value = clean_out(m)
    filled += 1

    if r <= 15:
        print(r, idx, ws.cell(row=r, column=2).value)

print("filled", filled, "rows; total apples =", accum[-1] if accum else None)
wb.save(OUT)
```

Plan: use the active sheet as the answer sheet, read A2:A8 from the cached workbook values, and extract digit characters while preserving leading zeros when present. Sort the unique digits ascending, write up to five digits into C:G for each row, and clear the remaining answer cells.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
if ws is None:
    ws = wb.worksheets[0]

def has_data(sheet):
    return any(sheet.cell(row=r, column=1).value is not None for r in range(2, 9))

source_title = None
if ws.title in vals.sheetnames and has_data(vals[ws.title]):
    source_title = ws.title
elif "Sheet2" in vals.sheetnames:
    source_title = "Sheet2"
else:
    source_title = vals.sheetnames[0]

source_vals = vals[source_title]
source_wb = wb[source_title] if source_title in wb.sheetnames else wb[ws.title]

def max_zero_run(fmt):
    best = cur = 0
    if not fmt:
        return 0
    for ch in fmt:
        if ch == "0":
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 0
    return best

def unique_digits(value, fmt):
    if value is None or isinstance(value, bool):
        return []

    if isinstance(value, (int, float)):
        if isinstance(value, float):
            s = str(int(value)) if value.is_integer() else str(value)
        else:
            s = str(value)

        if s.lstrip("-").isdigit():
            z = max_zero_run(fmt)
            if z > len(s):
                s = s.zfill(z)
    else:
        s = str(value)

    return sorted({ch for ch in s if ch.isdigit()})

for r in range(2, 9):
    fmt = source_wb.cell(row=r, column=1).number_format
    digits = unique_digits(source_vals.cell(row=r, column=1).value, fmt)

    for c in range(3, 8):
        ws.cell(row=r, column=c).value = None

    for i, d in enumerate(digits[:5]):
        ws.cell(row=r, column=3 + i).value = int(d)

    print(r, digits)

wb.save(OUT)
