from openpyxl.utils import range_boundaries
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "Sheet1" if "Sheet1" in wb.sheetnames else (wb.active.title if wb.active is not None else None)
if sheet_name is None:
    sheet_name = wb.sheetnames[0]

ws = wb[sheet_name]
vws = vals[sheet_name]

EPOCH = datetime(1899, 12, 30)


def to_datetime(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime(value.year, value.month, value.day)
    if isinstance(value, (int, float)):
        try:
            return EPOCH + timedelta(days=float(value))
        except Exception:
            return None

    text = str(value).strip()
    if not text:
        return None

    formats = (
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%d",
        "%m/%d/%Y %H:%M:%S",
        "%m/%d/%Y",
        "%d-%m-%Y",
        "%d/%m/%Y",
    )
    for fmt in formats:
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            pass
    return None


def norm_name(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    text = str(value).strip()
    if not text:
        return None
    return text.lower()


def build_table_map(sheet):
    mapping = {}

    try:
        tables = sheet.tables
    except Exception:
        tables = {}

    for table_name, table in tables.items():
        if table_name != "Table1":
            continue

        try:
            min_col, min_row, max_col, max_row = range_boundaries(table.ref)
        except Exception:
            continue

        name_col = None
        date_col = None

        try:
            for idx, col in enumerate(table.tableColumns):
                col_name = str(getattr(col, "name", "")).strip().lower()
                if col_name == "participant_name" and name_col is None:
                    name_col = min_col + idx
                elif col_name == "start_date" and date_col is None:
                    date_col = min_col + idx
        except Exception:
            pass

        if name_col is None or date_col is None:
            headers = {}
            for col in range(min_col, max_col + 1):
                header = sheet.cell(row=min_row, column=col).value
                if header is not None:
                    key = str(header).strip().lower()
                    if key not in headers:
                        headers[key] = col
            name_col = headers.get("participant_name")
            date_col = headers.get("start_date")

        if name_col is None or date_col is None:
            continue

        for row in range(min_row + 1, max_row + 1):
            name = norm_name(sheet.cell(row=row, column=name_col).value)
            if name is None:
                continue
            if name not in mapping:
                mapping[name] = to_datetime(sheet.cell(row=row, column=date_col).value)

        if mapping:
            return mapping

    for row in range(1, sheet.max_row + 1):
        a = norm_name(sheet.cell(row=row, column=1).value)
        b = norm_name(sheet.cell(row=row, column=2).value)
        if a == "participant_name" and b == "start_date":
            mapping = {}
            r = row + 1
            while r <= sheet.max_row:
                name = norm_name(sheet.cell(row=r, column=1).value)
                dt = to_datetime(sheet.cell(row=r, column=2).value)
                if name is None and dt is None:
                    break
                if name is not None and name not in mapping:
                    mapping[name] = dt
                r += 1
            if mapping:
                return mapping

    return mapping


table_map = build_table_map(vws)
print("Sheet:", sheet_name)
print("Table map:", {k: str(v) for k, v in table_map.items()})

answer_rows = [4, 5, 6, 11, 12, 13, 20, 21, 22]

for row in answer_rows:
    name = norm_name(vws.cell(row=row, column=4).value)
    outside_date = to_datetime(vws.cell(row=row, column=5).value)

    if name is not None and name in table_map:
        table_date = table_map[name]
        if table_date is None:
            table_date = EPOCH
        if outside_date is None:
            outside_date = EPOCH
        result = bool(table_date >= outside_date)
    else:
        result = False

    ws.cell(row=row, column=7).value = result
    print(f"Row {row}: name={name}, table_date={table_date}, outside_date={outside_date}, result={result}")

wb.save(OUT)
```

Load the cached values, group data rows by columns A and B, and keep only rows whose column E date equals the maximum date for that pair (rows without E are dropped). Compact the kept rows to the top of A3:G28, blanking the rest. Save the workbook with plain values.

```python
import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb["Sheet1"]
vws = vals["Sheet1"]

FIRST_ROW = 3
LAST_ROW = 28
COLS = 7

def clean_value(v):
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def norm_key(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def parse_date(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        formats = (
            "%Y/%m/%d", "%Y/%m", "%Y-%m-%d", "%Y-%m",
            "%m/%d/%Y", "%d/%m/%Y", "%m/%Y",
            "%Y/%m/%d %H:%M:%S", "%Y-%m-%d %H:%M:%S",
            "%Y/%m/%d %H:%M", "%Y-%m-%d %H:%M",
            "%Y/%m/%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S.%f",
        )
        for fmt in formats:
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
        try:
            return datetime.fromisoformat(s)
        except ValueError:
            pass
    return None

def date_key(d):
    if isinstance(d, datetime):
        return d.date()
    return d

rows = []
scan_last = max(vws.max_row, LAST_ROW)
for r in range(FIRST_ROW, scan_last + 1):
    a = vws.cell(r, 1).value
    b = vws.cell(r, 2).value
    e = vws.cell(r, 5).value

    if all(clean_value(vws.cell(r, c).value) is None for c in range(1, COLS + 1)):
        continue

    key = (norm_key(a), norm_key(b))
    if key[0] is None or key[1] is None:
        continue

    d = parse_date(e)
    if d is None:
        continue

    row_values = [vws.cell(r, c).value for c in range(1, COLS + 1)]
    if isinstance(e, str):
        row_values[4] = d
    rows.append((key, date_key(d), row_values))

max_dates = {}
for key, dk, _ in rows:
    if key not in max_dates or dk > max_dates[key]:
        max_dates[key] = dk

kept = [row_values for key, dk, row_values in rows if dk == max_dates[key]]

for r in range(FIRST_ROW, LAST_ROW + 1):
    for c in range(1, COLS + 1):
        ws.cell(r, c).value = None

for i, row_values in enumerate(kept[:LAST_ROW - FIRST_ROW + 1]):
    r = FIRST_ROW + i
    for c, v in enumerate(row_values, start=1):
        ws.cell(r, c).value = clean_value(v)

print("kept_rows", len(kept))
if kept:
    print("first_kept", kept[0])

wb.save(OUT)
