    kind = clean(master.cell(row=7, column=col).value).lower()
    if person and kind == "amount":
        amount_col_by_person[person] = col

# Explicit layout fallback: Result G:I -> Master-RM I, Result J:L -> Master-RM K
def fallback_col(result_col):
    return 9 if 7 <= result_col <= 9 else 11

# Find the "Total" row for each item in Master-RM
total_row_by_item = {}
for row in range(1, master.max_row + 1):
    a = clean(master.cell(row=row, column=1).value)
    b = clean(master.cell(row=row, column=2).value)
    if b.lower() == "total" and a:
        total_row_by_item[a] = row
    elif a.lower() == "total" and b:
        total_row_by_item[b] = row

# Loose fallback if the item/Total pair is not in columns A/B
for c in range(7, 13):
    item = clean(ws.cell(row=2, column=c).value)
    if item and item not in total_row_by_item:
        for row in range(1, master.max_row + 1):
            row_vals = [clean(master.cell(row=row, column=col).value) for col in range(1, master.max_column + 1)]
            if item in row_vals and any(x.lower() == "total" for x in row_vals):
                total_row_by_item[item] = row
                break

def to_number(v):
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return int(v) if float(v).is_integer() else float(v)
    s = clean(v)
    if not s:
        return None
    try:
        f = float(s)
        return int(f) if f.is_integer() else f
    except Exception:
        return s

def get_master_value(row, col):
    v = master.cell(row=row, column=col).value
    if v is None:
        # Fallback: sum the detail rows above this total row in the same column.
        start = 1
        for r in range(row - 1, 0, -1):
            if clean(master.cell(row=r, column=2).value).lower() == "total":
                start = r + 1
                break
        s = 0
        for r in range(start, row):
            cv = master.cell(row=r, column=col).value
            if isinstance(cv, (int, float)) and not isinstance(cv, bool):
                s += cv
        v = s
    return to_number(v)

